contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(true);
        // ensure c has funds so the revert (if any) is due to the receiver, not lack of balance
        require(address(this).balance >= amount);
        c.sendTo(address(this), 0); // top-level state-changing call to become owner-context (no-op transfer)
        // fund c by sending Ether via a zero-amount self path is not possible; instead require c holds enough
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sendTo(address(c), amount) { reverted = false; } catch { reverted = true; }
        assert(reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address receiver, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // fund c with `amount` so the balance is not the limiting factor
        c.sendTo(address(this), 0); // no-op call, keeps msg.sender consistency
        bool funded;
        // Give c Ether via a self-send? c has no receive; instead send via sendTo to this contract.
        // Use run's msg.value: we cannot read msg.value; instead transfer by calling sendTo to receiver==address(this).
        // Simplest: use payable receiver as a non-payable target via a fresh codeless address check.
        // Instead, make receiver a contract without receive: use address of c itself (C has no receive/fallback).
        address target = address(c);
        uint balBefore = address(c).balance;

        bool reverted;
        try c.sendTo(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

